<script setup lang="ts">type Product={name:string,category:string,image:string,alt:string,description:string,finishes:string[]}; const props=defineProps<{product:Product}>(); const inquiryUrl=computed(()=>`mailto:hello@example.com?subject=${encodeURIComponent(`Inquiry about ${props.product.name}`)}&body=${encodeURIComponent(`Hi Buildstone Construction, I'm interested in ${props.product.name}. Could I get more details and a quote?`)}`)</script>
<template><article class="product-card"><div class="product-image"><img :src="product.image" :alt="product.alt" width="900" height="675" loading="lazy"></div><div class="product-body"><h3>{{ product.name }}</h3><p class="finish-label">Available finishes</p><div class="swatches" :aria-label="`${product.finishes.length} finishes available`"><span v-for="(finish,index) in product.finishes" :key="finish" class="swatch" :style="{backgroundColor:finish}" :title="`Finish ${index+1}`"></span></div><p class="description">{{ product.description }}</p><a :href="inquiryUrl" :aria-label="`Ask about ${product.name} by email`">Ask about this product <span aria-hidden="true">→</span></a></div></article></template>
